-- 3. High-Performance Indexes for Partitioned Tables
-- ============================================================================
CREATE INDEX IF NOT EXISTS idx_search_logs_user_id ON search_logs(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_group_events_user_id ON group_events(user_id, created_at DESC);

-- ============================================================================
-- 4. Foreign Key & Operational Performance Indexes
-- ============================================================================
CREATE INDEX IF NOT EXISTS idx_username_reports_order_id ON username_reports(order_id);
CREATE INDEX IF NOT EXISTS idx_username_report_sources_report_id ON username_report_sources(report_id);
CREATE INDEX IF NOT EXISTS idx_valuation_backtests_model_version ON valuation_backtests(model_version);

-- ============================================================================
-- 5. Drop Redundant / Duplicate Indexes
-- ============================================================================
DROP INDEX IF EXISTS idx_user_stats_xp;
DROP INDEX IF EXISTS idx_orders_payload_status;

-- ============================================================================
-- 6. HOT (Heap-Only Tuples) Update Optimization with Fillfactor
-- ============================================================================
ALTER TABLE user_stats SET (fillfactor = 85);
ALTER TABLE users SET (fillfactor = 90);
ALTER TABLE managed_groups SET (fillfactor = 90);
ALTER TABLE managed_channels SET (fillfactor = 90);

-- ============================================================================
-- 7. High-Speed Trigram Fuzzy Search (pg_trgm extension & GIN indexes)
-- ============================================================================
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX IF NOT EXISTS idx_users_username_trgm ON users USING gin (username gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_clans_title_trgm ON clans USING gin (chat_title gin_trgm_ops);

